<?php require_once __DIR__.'/includes/auth.php'; require_login(['admin','hod']);$pdo=db();$pending=$pdo->query("SELECT r.tracking_no,r.session_name,c.course_code,c.course_title,s.stage_name,o.office_name,TIMESTAMPDIFF(DAY,r.current_since,NOW()) days,s.delay_days FROM result_records r JOIN courses c ON c.id=r.course_id JOIN status_stages s ON s.id=r.current_stage_id LEFT JOIN offices o ON o.id=r.current_office_id WHERE s.stage_order<7 ORDER BY days DESC")->fetchAll();$released=$pdo->query("SELECT r.tracking_no,r.session_name,c.course_code,c.course_title,c.level,r.current_since FROM result_records r JOIN courses c ON c.id=r.course_id JOIN status_stages s ON s.id=r.current_stage_id WHERE s.stage_name='Released to Students' ORDER BY r.current_since DESC")->fetchAll();$sessions=$pdo->query("SELECT session_name,COUNT(*) total,SUM(current_stage_id=7) released,COUNT(*)-SUM(current_stage_id=7) pending FROM result_records GROUP BY session_name ORDER BY session_name DESC")->fetchAll();$pageTitle='Reports | IFT';require __DIR__.'/includes/header.php';?><body class="portal-page"><header class="portal-header"><div class="portal-brand"><img src="assets/naits-logo.png"><div><strong>IFT Result Tracking</strong><span>Reports</span></div></div><a class="portal-back" href="<?=current_user()['role']==='hod'?'hod-dashboard.php':'admin-dashboard.php'?>">← Dashboard</a></header><main class="portal-main reports-main"><style>
/* Reports page only: keep the three report panels contained on laptops, desktops and TVs. */
.reports-main{width:auto;max-width:none;box-sizing:border-box;}
.reports-main .page-title{flex-wrap:wrap;}
.reports-main .export-actions{flex-wrap:wrap;}
.reports-main .report-grid{grid-template-columns:minmax(0,1fr) minmax(0,1fr);align-items:start;}
.reports-main .report-grid>.panel{min-width:0;width:100%;box-sizing:border-box;}
.reports-main .full-report{grid-column:1/-1;}
.reports-main .report-table-wrap{max-width:100%;overflow-x:auto;}
.reports-main .report-table-wrap table{min-width:0;width:100%;table-layout:fixed;}
.reports-main .report-table-wrap th,.reports-main .report-table-wrap td{white-space:normal;overflow-wrap:anywhere;word-break:normal;}
@media (min-width:1400px){.reports-main .report-grid{grid-template-columns:minmax(0,1.2fr) minmax(0,1fr);}}
@media (max-width:1050px) and (min-width:761px){.reports-main{padding-left:24px;padding-right:24px;}.reports-main .report-grid{grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:14px;}}
@media (max-width:760px){.reports-main{padding-left:14px;padding-right:14px;}.reports-main .report-grid{display:block;}.reports-main .report-grid>.panel{margin-bottom:14px;}.reports-main .full-report{grid-column:auto;}.reports-main .export-actions{width:100%;}.reports-main .export-actions>*{flex:1 1 180px;}}
</style>
<div class="page-title"><div><span class="kicker">REPORTS</span><h1>Result Reports</h1><p>Review pending results, delays and released results by session.</p></div><div class="export-actions"><button class="secondary-btn" onclick="window.print()">Print / Save PDF</button><?php if(current_user()['role']==='admin'):?><a class="primary-btn button-link" href="export.php?type=pending">Export Excel/CSV</a><?php endif;?></div></div><section class="report-grid"><div class="panel"><div class="panel-head"><div><span class="kicker">PENDING RESULTS</span><h2>Currently pending</h2></div></div><div class="table-wrap report-table-wrap"><table><thead><tr><th>Course</th><th>Stage</th><th>Office</th><th>Days</th></tr></thead><tbody><?php foreach($pending as $r):?><tr><td><strong><?=e($r['course_code'])?></strong><small><?=e($r['course_title'])?></small></td><td><?=e($r['stage_name'])?></td><td><?=e($r['office_name']??'—')?></td><td><?php if($r['delay_days']>0 && $r['days']>$r['delay_days']):?><span class="delay"><?=e($r['days'])?> days</span><?php else:?><?=e($r['days'])?> days<?php endif;?></td></tr><?php endforeach;if(!$pending):?><tr><td colspan="4">No pending results.</td></tr><?php endif;?></tbody></table></div></div><div class="panel"><div class="panel-head"><div><span class="kicker">RELEASED</span><h2>Recently released</h2></div></div><div class="table-wrap report-table-wrap"><table><thead><tr><th>Course</th><th>Level</th><th>Session</th><th>Date</th></tr></thead><tbody><?php foreach(array_slice($released,0,15) as $r):?><tr><td><strong><?=e($r['course_code'])?></strong><small><?=e($r['course_title'])?></small></td><td><?=e($r['level'])?></td><td><?=e($r['session_name'])?></td><td><?=e(date('d M Y',strtotime($r['current_since'])))?></td></tr><?php endforeach;if(!$released):?><tr><td colspan="4">No released results yet.</td></tr><?php endif;?></tbody></table></div></div><div class="panel full-report"><div class="panel-head"><div><span class="kicker">RELEASED PER SESSION</span><h2>Completion summary</h2></div></div><div class="table-wrap report-table-wrap"><table><thead><tr><th>Session</th><th>Total Received</th><th>Released</th><th>Pending</th><th>Completion</th></tr></thead><tbody><?php foreach($sessions as $r):$pct=$r['total']?round($r['released']/$r['total']*100,1):0;?><tr><td><?=e($r['session_name'])?></td><td><?=e($r['total'])?></td><td><?=e($r['released'])?></td><td><?=e($r['pending'])?></td><td><?=e($pct)?>%</td></tr><?php endforeach;if(!$sessions):?><tr><td colspan="5">No records yet.</td></tr><?php endif;?></tbody></table></div></div></section></main><?php require __DIR__.'/includes/footer.php'; ?>
